parameters.jsCode:
const body = $input.first().json.body;

const required = ['guest_name', 'episode_topic'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

return [{
  json: {
    valid: true,
    guestName: body.guest_name.trim(),
    guestTitle: body.guest_title || '',
    guestCompany: body.guest_company || '',
    guestWebsite: body.guest_website || '',
    episodeTopic: body.episode_topic.trim(),
    podcastName: body.podcast_name || $env.PODCAST_NAME || 'the podcast',
    podcastAudience: body.podcast_audience || $env.PODCAST_AUDIENCE || 'general audience',
    interviewDate: body.interview_date || '',
    hostName: body.host_name || $env.HOST_NAME || 'the host',
    hostEmail: body.host_email || $env.HOST_EMAIL || null,
    previousAppearances: body.previous_appearances || '',
    specificFocusAreas: body.specific_focus_areas || '',
    requestedAt: new Date().toISOString()
  }
}];

const guestSearch = $('Search Guest Background').first().json;
const interviewSearch = $('Search Past Interviews').first().json;
const input = $('Validate Input').first().json;

const guestResults = (guestSearch.results || []).map(r => ({
  title: r.title,
  url: r.url,
  snippet: (r.content || r.snippet || '').slice(0, 400)
}));

const interviewResults = (interviewSearch.results || []).map(r => ({
  title: r.title,
  url: r.url,
  snippet: (r.content || r.snippet || '').slice(0, 300)
}));

const autoAnswer = guestSearch.answer || '';

return [{
  json: {
    input,
    guestResults,
    interviewResults,
    autoAnswer,
    searchedAt: new Date().toISOString()
  }
}];

values.content:
Prepare a pre-interview briefing for the following guest.

Interview details:
- Guest: {{ $json.input.guestName }}{{ $json.input.guestTitle ? ', ' + $json.input.guestTitle : '' }}{{ $json.input.guestCompany ? ' at ' + $json.input.guestCompany : '' }}
- Episode topic: {{ $json.input.episodeTopic }}
- Podcast: {{ $json.input.podcastName }}
- Audience: {{ $json.input.podcastAudience }}
- Host: {{ $json.input.hostName }}
- Interview date: {{ $json.input.interviewDate || 'not specified' }}
- Specific areas to focus on: {{ $json.input.specificFocusAreas || 'none specified' }}
- Known previous appearances: {{ $json.input.previousAppearances || 'none noted' }}

Web research on guest:
Auto-summary: {{ $json.autoAnswer || 'not available' }}

Top search results:
{{ $json.guestResults.map((r, i) => `[${i+1}] ${r.title}\n${r.snippet}\nSource: ${r.url}`).join('\n\n') }}

Past interview appearances found:
{{ $json.interviewResults.map((r, i) => `[${i+1}] ${r.title}\n${r.snippet}\nSource: ${r.url}`).join('\n\n') || 'None found' }}

Generate the briefing as this JSON:
{
  "guest_name": "{{ $json.input.guestName }}",
  "episode_topic": "{{ $json.input.episodeTopic }}",
  "tldr": "3-sentence summary of who this person is and why they're interesting for this episode. Written like you're texting a colleague.",
  "background_snapshot": "A paragraph on their career arc — how they got to where they are, what makes their path interesting or unusual.",
  "key_expertise": ["3-5 specific areas they can speak with genuine authority on"],
  "notable_facts": ["3-5 interesting, specific, non-obvious things about this person that good research surfaced"],
  "known_positions": ["3-4 things they're publicly on record believing or advocating — be specific, not generic"],
  "unexplored_angles": [
    {
      "angle": "an angle other podcasts probably haven't covered",
      "why_interesting": "why this could lead somewhere good"
    }
  ],
  "handle_with_care": ["any sensitive topics, past controversies, or areas where the host should tread carefully — be honest"],
  "questions": {
    "openers": ["2-3 warm-up questions to get the guest comfortable"],
    "substantive": ["4-5 meaty questions that get into the real content"],
    "unexpected": ["2-3 questions they probably haven't been asked on other podcasts"],
    "closing": ["1-2 good closing questions"]
  },
  "what_to_avoid": "topics or framings that would make this interview feel like every other one they've done",
  "sources_consulted": ["list the URLs from search results that were most useful"]
}

