const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let briefing;
try {
  briefing = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
const input = $('Validate Input').first().json;
briefing._hostEmail = input.hostEmail;
briefing._podcastName = input.podcastName;
briefing._interviewDate = input.interviewDate;
return [{ json: briefing }];
